function catalogEffectSummary(skill){const effects=[...(skill.buffs||[]).map(name=>({name,scope:'self'})),...(skill.debuffs||[]).map(name=>({name,scope:'enemy'}))].filter((item,index,all)=>all.findIndex(x=>x.name===item.name&&x.scope===item.scope)===index);if(!effects.length)return'';return `<span class="skill-effect-summary" aria-label="강화·약화 효과">${effects.map(item=>{const duration=skill.timingEffects?.[item.name]?.duration;return `<span class="skill-effect-chip ${item.scope}">${builderEffectIcon(item.name,item.scope)}<span><b>${esc(item.name)}</b>${Number.isFinite(duration)?`<small>${seconds(duration)}</small>`:''}</span></span>`;}).join('')}</span>`;}

