function renderBuilderEquipment(){const host=document.querySelector('#equipment-control');if(!host)return;syncBuilderAutoPolicy();const order=equipmentOrder();D.baseSlots=order.slice(0,5).filter(Boolean);const counts={};for(const id of D.baseSlots){const s=byId(id);if(s)counts[s.family]=(counts[s.family]||0)+1;}const activeFamily=Object.keys(counts).find(f=>counts[f]>=3),slot=(index,label,kind)=>{const s=byId(order[index]),drag=s?'draggable="true"':'',skillId=s?`data-skill-id="${esc(s.id)}"`:'',enabled=s?!D.executionPolicy.disabled.includes(s.id):true,aria=s?`${label} 배치 ${esc(s.name)} · 드래그하여 이동`:`${label} 빈 슬롯 · 드롭 가능`;return `<div class="order-node builder-equipment-slot ${kind} ${s?'filled':''} ${s&&!enabled?'auto-off':''}" data-equipment-index="${index}" ${skillId} ${drag} aria-label="${aria}"><button type="button" class="order-pick equipment-pick" tabindex="-1"><small>${label}</small>${s?`${icon(s)}<b>${esc(s.name)}</b>${skillTags(s)}`:'<span class="slot-plus">+</span><b class="slot-empty-label">&nbsp;</b>'}</button>${s?autoControlButton(s):''}</div>`;};host.open=true;host.innerHTML=`<div class="builder-equipment-head"><b>스킬 배치</b><small>드래그로 이동·교환 · 1–5 계열 판정</small></div><div class="builder-equipment-layout"><div class="builder-equipment-number" aria-label="1번부터 5번까지 계열 판정 스킬">${Array.from({length:5},(_,i)=>slot(i,`${i+1}`,'number')).join('')}</div><div class="builder-equipment-function" aria-label="F1부터 F3까지 추가 스킬">${Array.from({length:3},(_,i)=>slot(i+5,`F${i+1}`,'function')).join('')}</div></div><div class="builder-equipment-result"><span>신식 · 1–5 기준</span><b>${activeFamily?esc(window.DosulCombat?.rules?.[activeFamily]?.name||activeFamily):'미개방'}</b></div>`;}
